import React, { forwardRef } from 'react';

import { MeterBarTooltipItem } from './MeterBarTooltipItem/MeterBarTooltipItem.js';
import { mergeTooltipActions } from '../../../../core/components/series-action/functions/mergeTooltipActions.js';
import { useChartActionsMenu } from '../../../../core/components/series-action/hooks/useChartActionsMenu.js';
import { ChartTooltip } from '../../../../core/components/tooltip/ChartTooltip/ChartTooltip.js';
import { TooltipBody } from '../../../../core/components/tooltip/section-components/TooltipBody.js';
import { useTooltipSeriesActions } from '../../../../core/components/tooltip/shared/hooks/useTooltipSeriesActions.js';
import { useMousePosition } from '../../../../core/hooks/useMousePosition.js';
import type { MouseCoordinate } from '../../../../core/types/overlays.js';
import { TooltipItem } from '../../../../core/types/tooltip.js';

interface MeterBarTooltipProps {
  items: TooltipItem[];
  isPinned: boolean;
}

// TODO: check if it's still needed once decoupling of the mouse tracking story is done (APPDEV-7070)
function isInitialPosition(mousePosition: MouseCoordinate) {
  const { x, y } = mousePosition;
  return x === 0 && y === 0;
}

const ESTIMATED_ITEM_HEIGHT_PX = 22;

export const MeterBarTooltip = forwardRef<HTMLDivElement, MeterBarTooltipProps>(
  (props: MeterBarTooltipProps, forwardedRef) => {
    const { isPinned, items } = props;
    const mousePosition = useMousePosition(!isPinned);

    const {
      onLeave: handleMenuLeave,
      selectedItem: selectedItemId,
      updateSelectedItem,
      actionsMenuRef,
    } = useChartActionsMenu();

    const bodyMinHeight = ESTIMATED_ITEM_HEIGHT_PX * items.length;

    const seriesActions = useTooltipSeriesActions(items, (item) => item.id);
    if (isInitialPosition(mousePosition)) {
      return null;
    }

    return (
      <ChartTooltip
        ref={forwardedRef}
        pinned={isPinned}
        position={mousePosition}
        onMouseLeave={handleMenuLeave}
        actionSelectionValue={{
          selectedItemId,
          actionsMenuRef,
          updateSelectedItem,
        }}
      >
        <TooltipBody
          style={{
            minHeight: `${bodyMinHeight}px`,
          }}
          virtualization={false}
        >
          {items.map((item, index) => (
            <MeterBarTooltipItem
              key={item.id}
              item={item}
              showDivider={index !== items.length - 1}
              actions={mergeTooltipActions(item, seriesActions)}
            />
          ))}
        </TooltipBody>
      </ChartTooltip>
    );
  },
);

MeterBarTooltip['displayName'] = 'MeterBarTooltip';
